1	package handover
2	
3	import (
4		"testing"
5		"time"
6	)
7	
8	// TestParseReceivedDetail：只认本工具写入的新旧固定格式；自由文字与残缺说明
9	// 一律视为没有明确记载，不解析出任何归属。
10	func TestParseReceivedDetail(t *testing.T) {
11		cases := []struct {
12			name   string
13			detail string
14			ok     bool
15			want   receivedAttribution
16		}{
17			{
18				name:   "新格式完整记载",
19				detail: "交接 H001（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：记录压力；后续负责人：王五",
20				ok:     true,
21				want:   receivedAttribution{handoverID: "H001", fromShift: "S001", toShift: "S002", kind: "track"},
22			},
23			{
24				name:   "新格式确认接收",
25				detail: "交接 H002（S002 -> S003）接班班次接收：确认接收",
26				ok:     true,
27				want:   receivedAttribution{handoverID: "H002", fromShift: "S002", toShift: "S003", kind: "confirm"},
28			},
29			{
30				name:   "旧格式只记载接班班次与方式",
31				detail: "接班班次 S002 接收：继续跟踪；跟踪说明：记录压力；后续负责人：王五",
32				ok:     true,
33				want:   receivedAttribution{toShift: "S002", kind: "track"},
34			},
35			{"自由文字", "当时口头打过招呼，先收下来", false, receivedAttribution{}},
36			{"残缺新格式缺接班班次", "交接 H001（S001 -> ）接班班次接收：确认接收", false, receivedAttribution{}},
37			{"残缺旧格式缺方式", "接班班次 S002 接收：", false, receivedAttribution{}},
38			{"无法识别的接收方式", "交接 H001（S001 -> S002）接班班次接收：待定", false, receivedAttribution{}},
39		}
40		for _, tc := range cases {
41			t.Run(tc.name, func(t *testing.T) {
42				got, ok := parseReceivedDetail(tc.detail)
43				if ok != tc.ok {
44					t.Fatalf("ok=%v, want %v（%+v）", ok, tc.ok, got)
45				}
46				if ok && got != tc.want {
47					t.Fatalf("归属=%+v, want %+v", got, tc.want)
48				}
49			})
50		}
51	}
52	
53	// TestSameReceivedEvent 逐条验证合并依据：操作人与实际时刻相同是前提，说明中
54	// 明确记载的字段逐项一致或未记载才合并；指向其他交接、班次或方式即冲突；
55	// 不同时区表示同一时刻视为相同时刻；自由文字不合并。
56	func TestSameReceivedEvent(t *testing.T) {
57		at := time.Date(2026, 10, 2, 11, 0, 0, 0, time.FixedZone("+08", 8*3600))
58		rcpt := receivedReceipt{
59			handoverID: "H001", fromShift: "S001", toShift: "S002",
60			kind: "track", operator: "李四", at: at, timeKnown: true,
61		}
62		ev := func(at time.Time, operator, detail string) ItemEvent {
63			return ItemEvent{At: at, Kind: "received", Operator: operator, Detail: detail}
64		}
65		canonical := "交接 H001（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：x；后续负责人：王五"
66		cases := []struct {
67			name string
68			ev   ItemEvent
69			want bool
70		}{
71			{"新格式全部一致", ev(at, "李四", canonical), true},
72			{"旧格式记载一致", ev(at, "李四", "接班班次 S002 接收：继续跟踪；跟踪说明：x；后续负责人：王五"), true},
73			{"不同时区同一时刻",
74				ev(time.Date(2026, 10, 2, 10, 0, 0, 0, time.FixedZone("+07", 7*3600)), "李四", canonical), true},
75			{"操作人不同", ev(at, "张三", canonical), false},
76			{"实际时刻不同", ev(at.Add(time.Minute), "李四", canonical), false},
77			{"交接编号冲突", ev(at, "李四", "交接 H999（S001 -> S002）接班班次接收：继续跟踪"), false},
78			{"交班班次冲突", ev(at, "李四", "交接 H001（S009 -> S002）接班班次接收：继续跟踪"), false},
79			{"接班班次冲突", ev(at, "李四", "交接 H001（S001 -> S003）接班班次接收：继续跟踪"), false},
80			{"接收方式冲突", ev(at, "李四", "交接 H001（S001 -> S002）接班班次接收：确认接收"), false},
81			{"旧格式接班班次冲突", ev(at, "李四", "接班班次 S003 接收：继续跟踪"), false},
82			{"旧格式方式冲突", ev(at, "李四", "接班班次 S002 接收：确认接收"), false},
83			{"自由文字", ev(at, "李四", "口头收的"), false},
84			{"非 received 事件", ItemEvent{At: at, Kind: "created", Operator: "李四", Detail: canonical}, false},
85		}
86		for _, tc := range cases {
87			t.Run(tc.name, func(t *testing.T) {
88				if got := sameReceivedEvent(tc.ev, rcpt); got != tc.want {
89					t.Fatalf("sameReceivedEvent=%v, want %v", got, tc.want)
90				}
91			})
92		}
93	}
94	
95	// TestReceivedMergeOrderIndependent：调换两条事项历史的保存顺序不改变哪一条
96	// 被合并；一条事项事件与一次交接接收各自至多匹配一次。
97	func TestReceivedMergeOrderIndependent(t *testing.T) {
98		at := time.Date(2026, 10, 2, 11, 0, 0, 0, time.UTC)
99		evToB := ItemEvent{At: at, Kind: "received", Operator: "李四",
100			Detail: "交接 H001（S001 -> S002）接班班次接收：继续跟踪"}
101		evToC := ItemEvent{At: at, Kind: "received", Operator: "李四",
102			Detail: "接班班次 S003 接收：确认接收"}
103		rcptB := receivedReceipt{
104			handoverID: "H001", fromShift: "S001", toShift: "S002",
105			kind: "track", operator: "李四", at: at, timeKnown: true,
106		}
107		for _, tc := range []struct {
108			name   string
109			events []ItemEvent
110		}{
111			{"乙班说明在前", []ItemEvent{evToB, evToC}},
112			{"乙班说明在后", []ItemEvent{evToC, evToB}},
113		} {
114			t.Run(tc.name, func(t *testing.T) {
115				m := newReceivedMerge(tc.events)
116				m.consider(rcptB)
117				used := 0
118				for i := range tc.events {
119					if m.isUsed(i) {
120						used++
121						if tc.events[i].Detail != evToB.Detail {
122							t.Fatalf("被合并的必须是指向乙班 H001 的说明：%s", tc.events[i].Detail)
123						}
124					}
125				}
126				if used != 1 {
127					t.Fatalf("应恰好合并一条，got %d", used)
128				}
129			})
130		}
131	}
132	
133	// TestReceivedMergeSkipsUnknownTime：处理时间缺失或零值的接收凭据不参与合并，
134	// 也不能拿任何其他时间代替；未匹配的事项事件原样保留。
135	func TestReceivedMergeSkipsUnknownTime(t *testing.T) {
136		at := time.Date(2026, 10, 2, 11, 0, 0, 0, time.UTC)
137		events := []ItemEvent{{At: at, Kind: "received", Operator: "李四",
138			Detail: "交接 H001（S001 -> S002）接班班次接收：确认接收"}}
139		m := newReceivedMerge(events)
140		m.consider(receivedReceipt{handoverID: "H001", fromShift: "S001", toShift: "S002",
141			kind: "confirm", operator: "李四"}) // timeKnown=false
142		if m.isUsed(0) {
143			t.Fatalf("未记录处理时间的接收不应合并事项事件")
144		}
145	}
