845				merge.consider(rcpt)
846			}
847		}
848	
849		// 事项自身历史：建立、修改、关闭原样保留；未被合并掉的 received 事件
850		// （旧数据、指向其他归属的说明、自由文字等）也原样保留。
851		for i, iev := range it.Events {
852			if iev.Kind == "received" && merge.isUsed(i) {
853				continue
854			}
855			add(JourneyEvent{
856				At: iev.At, TimeKnown: !iev.At.IsZero(),
857				Kind: iev.Kind, Operator: iev.Operator, Detail: iev.Detail,
858			}, "")
859		}
860	
861		sort.SliceStable(events, func(i, k int) bool {
862			a, b := events[i], events[k]
863			if a.ev.TimeKnown != b.ev.TimeKnown {
864				return a.ev.TimeKnown
865			}
866			if a.ev.TimeKnown && !a.ev.At.Equal(b.ev.At) {
867				return a.ev.At.Before(b.ev.At)
868			}
869			if a.group != b.group {
870				return a.group < b.group
871			}
872			return a.ord < b.ord
873		})
874		for _, ke := range events {
875			j.Events = append(j.Events, ke.ev)
876		}
877		return j, nil
878	}
