143			{"说明无明确归属信息", freeTextReceive, `"2026-10-02T11:00:00+08:00"`, 1},
144			{"记载另一个交接编号", otherHandoverTrack, `"2026-10-02T11:00:00+08:00"`, 1},
145			{"旧格式记载一致应合并", legacyTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
146			{"新格式记载一致应合并", canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
147			{"不同时区同一时刻应合并", canonicalTrackToBTZ, `"2026-10-02T11:00:00+08:00"`, 0},
148		}
149		for _, tc := range cases {
150			t.Run(tc.name, func(t *testing.T) {
151				svc := openLegacyService(t, journeyMergeRaw(tc.events, tc.processedAt))
152				j, err := svc.ItemJourney("I001")
153				if err != nil {
154					t.Fatalf("journey: %v", err)
155				}
156				if countKind(j.Events, "track") != 1 {
157					t.Fatalf("H001 的继续跟踪应始终展示一次：%v", journeyKinds(j))
158				}
159				if got := countKind(j.Events, "received"); got != tc.wantStandalone {
160					t.Fatalf("事项自身接收记录保留条数 want %d, got %d：%v", tc.wantStandalone, got, journeyKinds(j))
161				}
162			})
163		}
164	}
