166	// TestItemJourneyMergeReceptionDoesNotRewrite：单纯查询不改写任何历史、不移动
167	// 事项、不改变交接完成情况。
168	func TestItemJourneyMergeReceptionDoesNotRewrite(t *testing.T) {
169		raw := journeyMergeRaw(legacyConfirmToC+canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`)
170		svc := openLegacyService(t, raw)
171		if _, err := svc.ItemJourney("I001"); err != nil {
172			t.Fatalf("journey: %v", err)
173		}
174		// 重新打开同一文件，落盘内容必须与查询前逐字节一致。
175		path := svc.store.Path()
176		b, err := os.ReadFile(path)
177		if err != nil {
178			t.Fatalf("read: %v", err)
179		}
180		if string(b) != raw {
181			t.Fatalf("单纯查询不应重写数据文件")
182		}
183		it, err := svc.GetItem("I001")
184		if err != nil {
185			t.Fatalf("get item: %v", err)
186		}
187		if it.CurrentShiftID != "S002" || it.FollowOwner != "钱七" {
188			t.Fatalf("查询不应移动事项或替换负责人：%+v", it)
189		}
190		h, err := svc.GetHandover("H001")
191		if err != nil || !h.Completed() {
192			t.Fatalf("交接完成情况不应改变：%+v err=%v", h, err)
193		}
194	}
