func countKind(events []JourneyEvent, kind string) int {
	n := 0
	for _, ev := range events {
		if ev.Kind == kind {
			n++
		}
	}
	return n
}

// TestItemJourneyMergeReceptionSameOperatorSameTime：操作人与实际时刻相同并不
// 足以判定同一次接收。交给丙班的旧确认接收说明必须完整保留，H001 交给乙班的
// 继续跟踪只展示一次；两条历史在事项事件里的存放先后不能决定哪一条被隐藏；
// 旧说明没有对应交接清单时，既不能丢掉它，也不能凭空补上交接编号。
func TestItemJourneyMergeReceptionSameOperatorSameTime(t *testing.T) {
	for _, order := range []struct{ name, events string }{
		{"旧丙班说明在前", legacyConfirmToC + canonicalTrackToB},
		{"旧丙班说明在后", canonicalTrackToB + legacyConfirmToC},
	} {
		t.Run(order.name, func(t *testing.T) {
			svc := openLegacyService(t, journeyMergeRaw(order.events, `"2026-10-02T11:00:00+08:00"`))
			j, err := svc.ItemJourney("I001")
			if err != nil {
				t.Fatalf("journey: %v", err)
			}
			if countKind(j.Events, "track") != 1 {
				t.Fatalf("交给乙班的继续跟踪应只展示一次：%v", journeyKinds(j))
			}
			if countKind(j.Events, "received") != 1 {
				t.Fatalf("交给丙班的旧确认接收说明应原样保留一条：%v", journeyKinds(j))
			}
			if countKind(j.Events, "confirm") != 0 {
				t.Fatalf("H001 中不存在确认接收事件，丙班说明不应被改写成交接确认：%v", journeyKinds(j))
			}
			var standalone *JourneyEvent
			for i := range j.Events {
				if j.Events[i].Kind == "received" {
					standalone = &j.Events[i]
				}
			}
			if standalone == nil || !strings.Contains(standalone.Detail, "接班班次 S003 接收：确认接收") {
				t.Fatalf("保留的应是交给丙班的原说明：%+v", standalone)
			}
			if standalone.HandoverID != "" || standalone.ToShift != "" {
				t.Fatalf("无交接清单的旧说明不能凭空补交接编号或接班班次字段：%+v", standalone)
			}

			text := FormatItemJourney(j)
			if !strings.Contains(text, "接班班次 S003 接收：确认接收") {
				t.Fatalf("展示应完整保留交给丙班的原说明：\n%s", text)
			}
			if strings.Count(text, "交接 H001（S001 -> S002）继续跟踪") != 1 {
				t.Fatalf("交给乙班的继续跟踪应只出现一次：\n%s", text)
			}
			if !strings.Contains(text, "跟踪说明=每两小时记录压力") ||
				!strings.Contains(text, "后续负责人=王五") {
				t.Fatalf("继续跟踪应带出当时的跟踪说明与后续负责人：\n%s", text)
			}
			// 事项后来修改的负责人只体现在开头最新状态，不替换当时记录。
			if !strings.Contains(text, "后续负责人：钱七") {
				t.Fatalf("查询开头仍应展示事项最新负责人钱七：\n%s", text)
			}
			if len(j.Results) != 1 || j.Results[0].HandoverID != "H001" ||
				j.Results[0].Entry.Status != EntryTracking {
				t.Fatalf("各次交接当前结果应保持不变：%+v", j.Results)
			}
		})
	}
}

// TestItemJourneyMergeReceptionDistinguishingFacts：记载的接收方式、交接编号
// 不同，或说明根本没有明确归属信息时，事项历史各自保留；记载一致（含旧版本
// 格式、不同时区表示同一时刻）时才合并为同一次接收。
func TestItemJourneyMergeReceptionDistinguishingFacts(t *testing.T) {
	cases := []struct {
		name           string
		events         string
		processedAt    string
		wantStandalone int // 期望保留的事项自身 received 事件条数
	}{
		{"记载接收方式不同", canonicalConfirmToB, `"2026-10-02T11:00:00+08:00"`, 1},
		{"说明无明确归属信息", freeTextReceive, `"2026-10-02T11:00:00+08:00"`, 1},
		{"记载另一个交接编号", otherHandoverTrack, `"2026-10-02T11:00:00+08:00"`, 1},
		{"旧格式记载一致应合并", legacyTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
		{"新格式记载一致应合并", canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
		{"不同时区同一时刻应合并", canonicalTrackToBTZ, `"2026-10-02T11:00:00+08:00"`, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			svc := openLegacyService(t, journeyMergeRaw(tc.events, tc.processedAt))
			j, err := svc.ItemJourney("I001")
			if err != nil {
				t.Fatalf("journey: %v", err)
			}
			if countKind(j.Events, "track") != 1 {
				t.Fatalf("H001 的继续跟踪应始终展示一次：%v", journeyKinds(j))
			}
			if got := countKind(j.Events, "received"); got != tc.wantStandalone {
				t.Fatalf("事项自身接收记录保留条数 want %d, got %d：%v", tc.wantStandalone, got, journeyKinds(j))
			}
		})
	}
}

// TestItemJourneyMergeReceptionDoesNotRewrite：单纯查询不改写任何历史、不移动
// 事项、不改变交接完成情况。
func TestItemJourneyMergeReceptionDoesNotRewrite(t *testing.T) {
	raw := journeyMergeRaw(legacyConfirmToC+canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`)
	svc := openLegacyService(t, raw)
	if _, err := svc.ItemJourney("I001"); err != nil {
		t.Fatalf("journey: %v", err)
	}
	// 重新打开同一文件，落盘内容必须与查询前逐字节一致。
	path := svc.store.Path()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if string(b) != raw {
		t.Fatalf("单纯查询不应重写数据文件")
	}
	it, err := svc.GetItem("I001")
	if err != nil {
		t.Fatalf("get item: %v", err)
	}
	if it.CurrentShiftID != "S002" || it.FollowOwner != "钱七" {
		t.Fatalf("查询不应移动事项或替换负责人：%+v", it)
	}
	h, err := svc.GetHandover("H001")
	if err != nil || !h.Completed() {
		t.Fatalf("交接完成情况不应改变：%+v err=%v", h, err)
	}
}

// Package handover 是本地班次交接与未关闭事项的本地基线。
package handover

// Ready 表示基线可以运行。
func Ready() bool { return true }

// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
func entryCurrentResultLabel(s EntryStatus) string {
	switch s {
	case EntryPending:
		return "待处理（接班人尚未处理）"
	case EntryReturned:
		return "退回（等待交班人补充）"
	case EntryConfirmed:
		return "确认接收"
	case EntryTracking:
		return "继续跟踪（已接收）"
	case "":
		return "处理结果未记录"
	}
	return "处理结果无法识别（原值：" + string(s) + "）"
}

// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
func FormatJourneyEvent(ev JourneyEvent) string {
	when := "未记录"
	if ev.TimeKnown {
		when = fmtTime(ev.At)
	}
	who := whoIfRecorded(ev.Operator)
	where := ""
	if ev.HandoverID != "" {
		where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
	}
	switch ev.Kind {
	case "created":
		return when + " 事项建立"
	case "updated":
		return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
	case "closed":
		return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
	case "received":
		return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
	case "handover-init":
		// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
		return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
	case "return":
		return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
			when, where, ev.RoundSeq, who, ev.Reason)
	case "return-incomplete":
		// 当前结果是退回却没有退回轮次记录：退回确实发生过，但轮次序号、
		// 退回原因、补充与重新提交经过都没有可靠记录。处理人与时间各自使用
		// 当前保存的信息（缺失分别标为未记录），并明确提示退回历史不完整、
		// 原因未记录，不编造第几次退回，也不拿事项内容代替原因。
		return fmt.Sprintf("%s %s退回 操作人=%s（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
			when, where, who)
	case "resubmit":
		return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
			when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
			whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
	case "confirm":
		return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
	case "track":
		return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
			when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
	}
	return when + " " + ev.Kind
}

// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
func FormatItemJourney(j ItemJourney) string {
	var b strings.Builder
	writeItemHeader(&b, j.Item)

	b.WriteString("  处理经过：\n")
	if len(j.Events) == 0 {
		b.WriteString("    （暂无记录）\n")
	}
	for _, ev := range j.Events {
		b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
	}

	b.WriteString("  交接当前结果：\n")
	if !j.HasHandovers {
		b.WriteString("    暂无交接记录\n")
	}
	for _, r := range j.Results {
		// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）。
		operator, processedAt := currentProcessing(r.Entry)
		fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
			r.HandoverID, r.FromShift, r.ToShift,
			entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
	}
	return b.String()
}

// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
	var b strings.Builder
	state := "结束时未关闭"
	if snap.Closed {
		state = fmt.Sprintf("结束时已关闭（%s 于 %s）", snap.CloseOperator, fmtTimePtr(snap.ClosedAt))
	}
	fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
	fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
	fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
	fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
	if latest == nil {
		b.WriteString("  最新状态：事项记录已不存在\n")
		return b.String()
	}
	closeState := "未关闭"
	if latest.Closed {
		closeState = fmt.Sprintf("已关闭（%s 于 %s）", latest.CloseOperator, fmtTimePtr(latest.ClosedAt))
	}
	fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
		latest.CurrentShiftID, latest.FollowOwner, closeState)
	return b.String()
}

