// 被合并；一条事项事件与一次交接接收各自至多匹配一次。
func TestReceivedMergeOrderIndependent(t *testing.T) {
	at := time.Date(2026, 10, 2, 11, 0, 0, 0, time.UTC)
	evToB := ItemEvent{At: at, Kind: "received", Operator: "李四",
