     "created_at":"2026-10-02T10:00:00+08:00","completed_at":%s,
     "entries":[
       {"item_id":"I001","content":"泵房压力异常","severity":"important","constraints":"夜间禁动",
        "follow_owner":"王五","status":"tracking","operator":"李四","processed_at":%s,
